// Generated from public/bookmarks/admin.js, admin.css, admin-quick.js and admin-quick.css. Do not edit manually.
export const adminJavaScript = "const $ = id => document.getElementById(id);\nconst local = ['localhost','127.0.0.1'].includes(location.hostname);\nconst tokenKey = 'blog-bookmarks-admin-token';\nconst allowedFilters = ['pending','unread','readPending','private','decided','read','all','published','starred'];\nconst allowedSorts = ['new','old','recommended','title'];\nconst stateKeys = ['filter','sort','tag','q','page'];\nfunction readLocationState(){\n const query = new URLSearchParams(location.search);\n const rawPage = query.get('page') || '1';\n return {\n  filter: allowedFilters.includes(query.get('filter')) ? query.get('filter') : 'pending',\n  sort: allowedSorts.includes(query.get('sort')) ? query.get('sort') : 'new',\n  tag: (query.get('tag') || '').slice(0,80),\n  q: (query.get('q') || '').slice(0,100),\n  page: /^\\d+$/.test(rawPage) ? Math.min(100000, Math.max(1,Number(rawPage))) : 1\n };\n}\nconst state = {...readLocationState(), items:[], tags:[], pending:new Map(), writes:new Map()};\nlet refreshGeneration = 0;\nfunction syncControls(){\n $('filter').value=state.filter;\n $('sort').value=state.sort;\n $('q').value=state.q;\n $('tag').value=state.tag;\n}\nfunction updateLocation(replace=false){\n const url=new URL(location.href);\n for(const key of stateKeys)url.searchParams.delete(key);\n if(state.filter!=='pending')url.searchParams.set('filter',state.filter);\n if(state.sort!=='new')url.searchParams.set('sort',state.sort);\n if(state.tag)url.searchParams.set('tag',state.tag);\n if(state.q)url.searchParams.set('q',state.q);\n if(state.page!==1)url.searchParams.set('page',String(state.page));\n history[replace?'replaceState':'pushState'](history.state,'',url.href);\n}\nfunction navigate(next,{scrollTop=false,replace=false}={}){\n Object.assign(state,next);\n state.pending.clear();\n syncControls();\n updateLocation(replace);\n void refresh();\n if(scrollTop)window.scrollTo({top:0,behavior:'auto'});\n}\nconst esc = s => String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst dateText = value => value ? new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value)) : '';\nfunction headers(){const h={};if(local&&sessionStorage.getItem(tokenKey))h.Authorization='Bearer '+sessionStorage.getItem(tokenKey);return h;}\nasync function request(path, method='GET', body) {\n const r=await fetch('/bookmarks/api/admin'+path,{method,headers:{...headers(),...(body!==undefined?{'Content-Type':'application/json'}:{})},credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});\n const x=await r.json().catch(()=>({error:'伺服器回應格式錯誤'}));\n if(!r.ok)throw Error(x.error||'HTTP '+r.status);\n return x;\n}\nfunction status(msg,error=false){$('message').textContent=msg;$('message').classList.toggle('error',error);}\nfunction options(){const q=new URLSearchParams();for(const k of ['filter','sort','tag','q','page'])q.set(k,state[k]);return q.toString();}\nconst levelName=['未讀','已讀 · 待決定','已讀 · 確定不公開','已公開','★ 已推薦'];\nfunction itemHtml(b) {\n const label=levelName[b.status]||'';\n const target=b.preferred_url||b.redirect_url||b.url;\n const source=target!==b.url?'<div class=\"source-reference\">原始網址：<a href=\"'+esc(b.url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">'+esc(b.url)+'</a></div>':'';\n const originalTitle=b.title_original&&b.title_original!==b.title?'<div class=\"original-title\" lang=\"en\">'+esc(b.title_original)+'</div>':'';\n const statusDate=b.status>=3?' · '+(b.status===4?'推薦':'公開')+' '+dateText(b.status_at||b.starred_at||b.published_at):'';\n const info='<div class=\"meta\">加入 '+esc(dateText(b.created_at))+' · '+esc(new URL(b.url).hostname)+esc(statusDate)+'</div>';\n const tagNames=new Set(b.tags.map(x=>x.toLowerCase()));\n const choices=state.tags.map(t=>'<button type=\"button\" data-tag-name=\"'+esc(t.name)+'\" aria-pressed=\"'+String(tagNames.has(t.name.toLowerCase()))+'\">'+esc(t.name_zh||t.name)+'</button>').join('');\n const picker='<details class=\"category-picker\"><summary>分類：'+(b.tags.length?b.tags.map(t=>esc(state.tags.find(x=>x.name.toLowerCase()===t.toLowerCase())?.name_zh||t)).join('、'):'未分類')+' · 點擊選擇</summary><div class=\"category-choices\">'+choices+'</div><form class=\"add-category\" data-add-tag><input name=\"newtag\" maxlength=\"80\" placeholder=\"新增分類名稱\" aria-label=\"新增分類\"><button type=\"submit\">新增並選取</button></form></details>';\n const note=b.status>=3?'<a class=\"write-note\" href=\"/notes/editor/?bookmark='+encodeURIComponent(b.id)+'\" target=\"_blank\" rel=\"noopener\">寫隨筆 ↗</a>':'';\n const blocked=!b.tags.length||b.savingTags;\n const disabled=blocked?' disabled title=\"請先選擇至少一個分類並完成儲存\"':'';\n const actions='<div class=\"actions\"><button type=\"button\" data-decision=\"2\">不公開</button><button type=\"button\" data-decision=\"3\"'+disabled+'>公開</button><button type=\"button\" data-decision=\"4\"'+disabled+'>推薦</button><button type=\"button\" data-edit>編輯</button>'+note+'</div>';\n return '<article class=\"item\" data-id=\"'+esc(b.id)+'\"><div class=\"item-header\"><div class=\"item-heading\"><a class=\"title\" href=\"'+esc(target)+'\" target=\"_blank\" rel=\"noopener noreferrer\" data-read=\"'+esc(b.id)+'\">'+esc(b.title)+' ↗</a>'+originalTitle+info+source+'</div><span class=\"status-name\">'+label+'</span></div>'+(b.summary?'<p class=\"summary\">'+esc(b.summary)+'</p>':'')+picker+actions+'</article>';\n}\nfunction renderItem(b){\n const article=[...document.querySelectorAll('#items [data-id]')].find(el=>el.dataset.id===b.id);\n if(!article)return;\n const open=Boolean(article.querySelector('.category-picker')?.open);\n article.outerHTML=itemHtml(b);\n if(open)[...document.querySelectorAll('#items [data-id]')].find(el=>el.dataset.id===b.id)?.querySelector('.category-picker')?.setAttribute('open','');\n}\nasync function persistStatus(b,target){\n const previous=b.status;\n b.status=target;\n renderItem(b);\n const prior=state.writes.get(b.id)||Promise.resolve();\n const chain=prior.catch(()=>{}).then(()=>request('/'+b.id,'PATCH',{status:target}));\n state.writes.set(b.id,chain);\n try {\n  const item=await chain;\n  if(b.status===target)Object.assign(b,item);\n  status('已儲存「'+levelName[target]+'」');\n  return item;\n }catch(e){\n  if(b.status===target)b.status=previous;\n  renderItem(b);\n  status(e.message,true);\n  throw e;\n }\n}\nasync function refresh() {\n const generation=++refreshGeneration;\n try {\n  status('載入中…');\n  const [data,tags]=await Promise.all([request('/?'+options()),request('/tags')]);\n  if(generation!==refreshGeneration)return;\n  if(state.page>data.pages){\n   navigate({page:data.pages},{replace:true});\n   return;\n  }\n  state.items=data.items;\n  state.tags=tags;\n  $('items').innerHTML=state.items.map(itemHtml).join('')||'<p class=\"empty\">此篩選目前沒有書籤。</p>';\n  $('pager').innerHTML='<button id=\"prev\" '+(data.page<=1?'disabled':'')+'>上一頁</button><span>第 '+data.page+' / '+data.pages+' 頁 · '+data.total+' 筆'+'</span><button id=\"next\" '+(data.page>=data.pages?'disabled':'')+'>下一頁</button>';\n  $('prev').onclick=()=>navigate({page:state.page-1},{scrollTop:true});\n  $('next').onclick=()=>navigate({page:state.page+1},{scrollTop:true});\n  $('tag').innerHTML='<option value=\"\">全部標籤</option>'+tags.map(t=>'<option value=\"'+esc(t.id)+'\"'+(state.tag===t.id?' selected':'')+'>'+esc(t.name_zh||t.name)+' ('+t.count+')</option>').join('');\n  syncControls();\n  status('');\n }catch(e){if(generation===refreshGeneration)status(e.message,true);}\n}\nfunction edit(b) {\n $('editId').value=b?.id||'';\n $('editTitle').value=b?.title_zh||b?.title||'';\n $('editOriginalTitle').value=b?.title_original||'';\n $('editRedirectUrl').value=b?.redirect_url||'';\n $('editUrl').value=b?.url||'';\n $('editSummary').value=b?.summary||'';\n $('editHeading').textContent=b?'編輯書籤':'新增書籤';\n $('deleteItem').disabled=!b;\n $('editDialog').showModal();\n}\n$('app').innerHTML=`\n<header><h1>書籤管理 <small>Bookmarks</small></h1><nav><a href=\"/bookmarks/admin/quick/\">快速處理</a> · <a href=\"/bookmarks/\" target=\"_blank\" rel=\"noopener\">公開列表 ↗</a></nav></header>\n<div class=\"auth\" id=\"auth\"></div>\n<form class=\"filters\" id=\"filters\">\n <select id=\"filter\" aria-label=\"狀態\"><option value=\"pending\">待決定（未讀＋已讀待決定）</option><option value=\"unread\">未讀</option><option value=\"readPending\">已讀待決定</option><option value=\"private\">確定不公開</option><option value=\"decided\">已決定（不公開＋公開＋推薦）</option><option value=\"published\">公開及推薦</option><option value=\"starred\">推薦</option><option value=\"read\">全部已讀</option><option value=\"all\">全部</option></select>\n <select id=\"tag\" aria-label=\"標籤\"><option value=\"\">全部標籤</option></select>\n <select id=\"sort\" aria-label=\"排序\"><option value=\"new\">加入時間：最新</option><option value=\"old\">加入時間：最舊</option><option value=\"recommended\">推薦優先</option><option value=\"title\">標題</option></select>\n <button type=\"button\" id=\"manageTags\">標籤中英對照</button>\n <input id=\"q\" placeholder=\"搜尋標題、網址、摘要\" aria-label=\"搜尋書籤\">\n <button id=\"searchBtn\" type=\"submit\">搜尋</button>\n <button id=\"new\" type=\"button\">＋ 新增</button>\n</form>\n<div id=\"message\" role=\"status\" aria-live=\"polite\"></div>\n<div id=\"items\"></div><nav id=\"pager\" class=\"pager\"></nav>\n<dialog id=\"editDialog\" aria-labelledby=\"editHeading\"><form id=\"editForm\">\n <h2 id=\"editHeading\">編輯書籤</h2><input id=\"editId\" type=\"hidden\">\n <label>繁體中文標題<input id=\"editTitle\" required maxlength=\"500\" autocomplete=\"off\"></label>\n <label>原文標題（例如英文）<input id=\"editOriginalTitle\" maxlength=\"500\" autocomplete=\"off\"></label>\n <label>原始網址<input id=\"editUrl\" type=\"url\" required autocomplete=\"url\"></label>\n <label>重導向網址（選填，優先開啟）<input id=\"editRedirectUrl\" type=\"url\" autocomplete=\"off\"></label>\n <label>網站摘要（選填）<textarea id=\"editSummary\" maxlength=\"5000\"></textarea></label>\n <div class=\"dialog-actions\"><button type=\"submit\">儲存書籤</button><button type=\"button\" id=\"cancelEdit\">取消</button><button type=\"button\" id=\"deleteItem\">刪除</button></div>\n</form></dialog>\n<dialog id=\"tagsDialog\" aria-labelledby=\"tagsHeading\"><form id=\"tagsForm\">\n <h2 id=\"tagsHeading\">書籤標籤中英對照</h2>\n <p class=\"tag-hint\">後台與公開頁面優先顯示中文分類名稱。標籤 ID 與既有書籤關聯不會因改名而改變。</p>\n <div class=\"tag-columns\"><b>English</b><b>繁體中文</b><b>筆數</b></div>\n <div id=\"tagRows\"></div>\n <div class=\"dialog-actions\"><button type=\"submit\">儲存對照</button><button type=\"button\" id=\"closeTags\">關閉</button></div>\n </form></dialog>`;\nif(local){\n $('auth').innerHTML='<input id=\"token\" type=\"password\" autocomplete=\"off\" placeholder=\"本機管理 Token\"><button id=\"login\">登入</button><span class=\"hint\">Token 僅儲存在此分頁</span>';\n $('token').value=sessionStorage.getItem(tokenKey)||'';\n $('login').onclick=()=>{sessionStorage.setItem(tokenKey,$('token').value);refresh();};\n}\nconst tokenTools=document.createElement('section');\ntokenTools.className='token-tools';\ntokenTools.innerHTML='<button id=\"generateToken\" type=\"button\">產生 Tampermonkey Token</button><span class=\"hint\">重新產生會使舊 Token 失效。</span><div id=\"tokenResult\" hidden><input id=\"tokenValue\" readonly aria-label=\"一次性新增 Token\"><button id=\"copyToken\" type=\"button\">複製</button></div>';\n$('auth').after(tokenTools);\n$('generateToken').onclick=async()=>{\n if(!confirm('產生新 Token 後，舊 Token 將失效。確定繼續？'))return;\n try{const data=await request('/ingest-token','POST',{});$('tokenValue').value=data.token;$('tokenResult').hidden=false;status('Token 僅顯示這一次，請複製至 Tampermonkey。');}\n catch(e){status(e.message,true);}\n};\n$('copyToken').onclick=async()=>{\n try{await navigator.clipboard.writeText($('tokenValue').value);status('Token 已複製');}\n catch{$('tokenValue').select();status('請複製已選取的 Token');}\n};\n$('filters').onsubmit=e=>{\n e.preventDefault();\n navigate({q:$('q').value.trim(),page:1},{scrollTop:true});\n};\nfor(const id of ['filter','tag','sort']){\n $(id).addEventListener('change',()=>{\n  navigate({filter:$('filter').value,tag:$('tag').value,sort:$('sort').value,page:1},{scrollTop:true});\n });\n}\nfunction openTags(){\n $('tagRows').innerHTML=state.tags.map(t=>\n  '<div class=\"tag-row\" data-tag-id=\"'+esc(t.id)+'\">' +\n  '<input class=\"tag-en\" maxlength=\"80\" aria-label=\"英文標籤 '+esc(t.name)+'\" value=\"'+esc(t.name)+'\">' +\n  '<input class=\"tag-zh\" maxlength=\"80\" aria-label=\"中文標籤 '+esc(t.name)+'\" value=\"'+esc(t.name_zh||'')+'\" placeholder=\"公開中文名稱\">' +\n  '<span class=\"tag-count\">'+Number(t.count||0)+'</span></div>'\n ).join('');\n $('tagsDialog').showModal();\n}\n$('manageTags').onclick=openTags;\n$('closeTags').onclick=()=>$('tagsDialog').close();\n$('tagsForm').onsubmit=async e=>{\n e.preventDefault();\n const save=$('tagsForm').querySelector('button[type=\"submit\"]');\n save.disabled=true;\n let count=0;\n try{\n  for(const row of $('tagRows').querySelectorAll('[data-tag-id]')){\n   const id=row.dataset.tagId;\n   const current=state.tags.find(x=>x.id===id);\n   const name=row.querySelector('.tag-en').value.trim();\n   const name_zh=row.querySelector('.tag-zh').value.trim();\n   if(!current||!name)throw Error('英文標籤不得為空');\n   if(current.name===name && (current.name_zh||'')===name_zh)continue;\n   await request('/tags/'+encodeURIComponent(id),'PATCH',{name,name_zh});\n   count++;\n  }\n  $('tagsDialog').close();\n  await refresh();\n  status(count?'已儲存 '+count+' 個標籤的中英對照':'標籤未變更');\n }catch(error){status('標籤儲存失敗：'+error.message,true);}\n finally{save.disabled=false;}\n};\n$('new').onclick=()=>edit(null);\n$('cancelEdit').onclick=()=>$('editDialog').close();\n$('items').addEventListener('click',async e=>{\n const itemElement=e.target.closest('[data-id]');if(!itemElement)return;\n const b=state.items.find(x=>x.id===itemElement.dataset.id);if(!b)return;\n if(e.target.closest('[data-read]')){\n  if(b.status===0)persistStatus(b,1).then(()=>{if(state.filter==='unread')void refresh();}).catch(()=>{});\n  return;\n }\n if(e.target.closest('[data-edit]')){edit(b);return;}\n const tag=e.target.closest('[data-tag-name]');\n if(tag){\n  const name=tag.dataset.tagName,old=[...b.tags];\n  b.tags=old.some(t=>t.toLowerCase()===name.toLowerCase())?\n   old.filter(t=>t.toLowerCase()!==name.toLowerCase()):[...old,name];\n  b.savingTags=true;\n  renderItem(b);\n  try{\n   const updated=await request('/'+b.id,'PATCH',{tags:b.tags});\n   Object.assign(b,updated);\n   state.tags=await request('/tags');\n  }catch(error){b.tags=old;status(error.message,true);}\n  finally{b.savingTags=false;renderItem(b);}\n  return;\n }\n const decision=e.target.closest('[data-decision]');\n if(decision){\n  const level=Number(decision.dataset.decision);\n  if(level>=3&&(!b.tags.length||b.savingTags)){\n   status('公開或推薦前，請先選擇並儲存至少一個分類',true);return;\n  }\n  const queue=['pending','unread','readPending'].includes(state.filter);\n  const previous=b.status;\n  if(queue){\n   itemElement.remove();\n   state.items=state.items.filter(x=>x.id!==b.id);\n   if(!state.items.length)$('items').innerHTML='<p class=\"empty\">正在載入下一筆…</p>';\n  }\n  try{\n   await request('/'+b.id,'PATCH',{status:level});\n   await refresh();\n   status('已決定：'+levelName[level]);\n  }catch(error){\n   b.status=previous;\n   await refresh();\n   status(error.message,true);\n  }\n }\n});\n$('items').addEventListener('submit',async e=>{\n const form=e.target.closest('[data-add-tag]');if(!form)return;\n e.preventDefault();\n const element=form.closest('[data-id]');\n const b=state.items.find(x=>x.id===element?.dataset.id);\n const name=form.elements.newtag.value.trim();\n if(!b||!name||name.length>80)return;\n const old=[...b.tags];\n if(!b.tags.some(x=>x.toLowerCase()===name.toLowerCase()))b.tags.push(name);\n b.savingTags=true;renderItem(b);\n try{\n  const updated=await request('/'+b.id,'PATCH',{tags:b.tags});\n  Object.assign(b,updated);\n  state.tags=await request('/tags');\n  renderItem(b);\n  status('已加入分類：'+name);\n }catch(error){b.tags=old;status(error.message,true);}\n finally{b.savingTags=false;renderItem(b);}\n});\n\n$('editForm').onsubmit=async e=>{\n e.preventDefault();\n const id=$('editId').value;\n const body={title:$('editTitle').value,title_zh:$('editTitle').value,title_original:$('editOriginalTitle').value,url:$('editUrl').value,redirect_url:$('editRedirectUrl').value,summary:$('editSummary').value};\n try{await request(id?'/'+id:'',id?'PATCH':'POST',body);$('editDialog').close();await refresh();status('已儲存');}\n catch(err){status(err.message,true);}\n};\n$('deleteItem').onclick=async()=>{\n const id=$('editId').value;if(!id||!confirm('確定刪除這個書籤？'))return;\n try{await request('/'+id,'DELETE');state.pending.delete(id);$('editDialog').close();await refresh();status('已刪除');}\n catch(err){status(err.message,true);}\n};\nsyncControls();\nwindow.addEventListener('popstate',()=>{\n Object.assign(state,readLocationState());\n state.pending.clear();\n syncControls();\n void refresh();\n window.scrollTo({top:0,behavior:'auto'});\n});\nvoid refresh();\n";
export const adminStylesheet = ":root {\n  color-scheme:light dark;\n  --bg:#f8fafc; --surface:#fff; --ink:#172033; --muted:#64748b;\n  --line:#d8e0eb; --accent:#2563eb; --soft:#eff6ff;\n  font:16px/1.5 system-ui,'Segoe UI','Microsoft JhengHei',sans-serif;\n  background:var(--bg);color:var(--ink);\n}\n*,*::before,*::after{box-sizing:border-box}\nhtml,body{margin:0;min-height:100%;width:100%}\nbutton,input,select,textarea{font:inherit;color:inherit}\nbutton,select,input,textarea{border:1px solid var(--line);border-radius:8px;background:var(--surface);padding:8px 10px}\nbutton{cursor:pointer;font-weight:550}\nbutton:hover:enabled{border-color:var(--accent);color:var(--accent)}\nbutton:disabled{opacity:.45;cursor:not-allowed}\na{color:var(--accent);text-decoration:none}\na:hover{text-decoration:underline}\nbutton:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n#app{max-width:1100px;margin:auto;padding:20px 24px 80px}\nheader{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:16px}\nheader h1{font-size:1.6rem;letter-spacing:-.02em;margin:0;font-weight:750}\nheader a{font-size:.85rem}\n.filters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr)) auto;gap:9px;margin:12px 0 14px;align-items:center}\n.filters select,.filters input{min-width:0;width:100%}\n.filters input#q{grid-column:1/3}\n#searchBtn{grid-column:3/4}\n#manageTags{grid-column:4/5}\n#new{grid-column:4/5;background:var(--accent);border-color:var(--accent);color:#fff}\n#new:hover{filter:brightness(.95);color:#fff}\n#message{color:var(--muted);min-height:1.5em;font-size:.84rem;margin:8px 0}\n#message.error{color:#dc2626}\n.item{border:1px solid var(--line);background:var(--surface);border-radius:12px;padding:16px 18px;margin:10px 0;box-shadow:0 2px 8px #00000006;min-width:0}\n.item.pending{border-color:color-mix(in srgb,var(--accent),var(--line) 50%);box-shadow:0 0 0 2px color-mix(in srgb,var(--accent),transparent 92%)}\n.item-header{display:flex;align-items:flex-start;justify-content:space-between;gap:14px}\n.item-heading{min-width:0;flex:1}\n.title{font-weight:670;font-size:1.08rem;line-height:1.45;overflow-wrap:anywhere}\n.meta{font-size:.78rem;color:var(--muted);margin-top:6px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}\n.summary{font-size:.9rem;line-height:1.65;color:var(--muted);margin:10px 0 2px;overflow-wrap:anywhere;white-space:pre-wrap}\n.tagline{font-size:.82rem;color:var(--accent);margin:8px 0 0}\n.status-name{font-size:.76rem;white-space:nowrap;border:1px solid var(--line);background:var(--soft);color:var(--accent);padding:2px 9px;border-radius:999px}\n.actions{border-top:1px solid var(--line);margin-top:14px;padding-top:11px;display:flex;align-items:center;flex-wrap:wrap;gap:12px 18px}\n.actions label{display:inline-flex;align-items:center;gap:5px;font-size:.85rem;cursor:pointer;white-space:nowrap}\n.actions input{width:20px;height:20px;accent-color:var(--accent);margin:0}\n.actions button{font-size:.83rem;padding:6px 9px}\n.actions .write-note{font-size:.84rem}\n.decision-row{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-top:11px;padding-top:11px;border-top:1px dashed var(--line)}\n.decision-row .finish{background:var(--accent);color:#fff;border-color:var(--accent)}\n.decision-row .finish:hover{color:#fff;filter:brightness(.95)}\n.decision-row .private{font-size:.84rem}\n.decision-row p{font-size:.77rem;color:var(--muted);margin:0;flex:1}\n.pager{display:flex;justify-content:space-between;align-items:center;gap:9px;padding:16px 2px;font-size:.86rem}\n.pager button{min-width:75px}\n.auth{margin:0 0 12px;display:flex;align-items:center;gap:8px}\n.auth input{flex:1;max-width:420px;min-width:0}\n.hint{font-size:.77rem;color:var(--muted)}\n.token-tools{font-size:.82rem;display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:0 0 16px}\n#tokenResult{display:flex;flex:1;gap:8px;align-items:center}\n#tokenResult[hidden]{display:none}\n#tokenValue{width:min(70vw,500px);min-width:0;font:11px ui-monospace,Consolas,monospace}\ndialog{width:min(95vw,660px);max-height:90dvh;overflow:auto;margin:auto;padding:0;border:1px solid var(--line);border-radius:14px;background:var(--surface);color:var(--ink);box-shadow:0 22px 80px #0005}\ndialog::backdrop{background:rgba(8,15,32,.66);backdrop-filter:blur(2px)}\ndialog form{display:flex;flex-direction:column;gap:14px;padding:24px}\ndialog h2{font-size:1.35rem;margin:0 0 3px;line-height:1.3}\ndialog label{display:flex;flex-direction:column;gap:6px;font-size:.83rem;font-weight:550;color:var(--muted)}\ndialog input,dialog textarea{width:100%;min-width:0;color:var(--ink);font-weight:400}\ndialog input[type=url]{font-size:.87rem}\ndialog textarea{min-height:160px;resize:vertical;line-height:1.6}\ndialog .dialog-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding-top:6px}\ndialog .dialog-actions button:first-child{background:var(--accent);color:#fff;border-color:var(--accent)}\ndialog #deleteItem{margin-left:auto;color:#dc2626}\ndialog #deleteItem:disabled{display:none}\n@media(max-width:650px){\n #app{padding:14px 12px 56px}header h1{font-size:1.35rem}\n .filters{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}\n .filters #filter,.filters #tag{grid-column:auto}\n .filters #sort{grid-column:1/2}\n .filters #manageTags{grid-column:2/3}\n .filters #q{grid-column:1/-1}\n #searchBtn{grid-column:1/2}\n #new{grid-column:2/3}\n .item{padding:13px 12px;margin:9px 0;border-radius:10px}\n .title{font-size:1rem}\n .actions{gap:11px 14px}\n .actions label{font-size:.81rem}\n .actions input{width:22px;height:22px}\n .decision-row{gap:8px}\n dialog{width:calc(100vw - 18px);max-height:calc(100dvh - 22px)}\n dialog form{padding:18px 15px;gap:12px}\n dialog textarea{min-height:140px}\n}\n@media(prefers-color-scheme:dark){:root{--bg:#111827;--surface:#172033;--ink:#e2e8f0;--muted:#a6b2c4;--line:#384355;--accent:#60a5fa;--soft:#1a2d49}}\n\n\n.tag-hint{font-size:.85rem;line-height:1.6;color:var(--muted);margin:0}\n.tag-columns,.tag-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) 42px;gap:7px;align-items:center}\n.tag-columns{font-size:.8rem;color:var(--muted);margin:6px 0;font-weight:600}\n#tagRows{max-height:min(55dvh,530px);overflow:auto;display:grid;gap:7px}\n.tag-row input{min-width:0;width:100%;font-size:.88rem}\n.tag-count{text-align:center;color:var(--muted);font-size:.8rem;font-variant-numeric:tabular-nums}\n@media(max-width:650px){.tag-columns,.tag-row{grid-template-columns:minmax(0,1fr) minmax(0,1fr) 28px;gap:5px}.tag-row input{padding:8px 5px;font-size:.83rem}}\n\n/* Entire summaries are visible; categories are edited directly below each summary. */\n.original-title{color:var(--muted);font-size:.85rem;line-height:1.5;margin-top:3px;overflow-wrap:anywhere}\n.source-reference{font-size:.78rem;color:var(--muted);margin-top:6px;overflow-wrap:anywhere}\n.source-reference a{color:inherit;text-decoration:underline}\n.category-picker{margin:13px 0 0;border:1px solid var(--line);border-radius:8px;padding:8px 10px}\n.category-picker summary{cursor:pointer;font-size:.85rem;color:var(--accent);overflow-wrap:anywhere}\n.category-choices{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}\n.category-choices button{font-size:.8rem;padding:5px 9px}\n.category-choices button[aria-pressed=true]{background:var(--soft);color:var(--accent);border-color:var(--accent)}\n.add-category{display:flex;gap:8px;margin-top:10px}\n.add-category input{min-width:0;flex:1}\n.add-category button{white-space:nowrap}\n.actions [data-decision]{font-weight:650}\n.actions [data-decision=\"2\"]{background:transparent}\n.actions [data-decision=\"3\"]{background:var(--soft);color:var(--accent)}\n.actions [data-decision=\"4\"]{background:var(--accent);color:white;border-color:var(--accent)}\n";
export const quickJavaScript = "const $ = id => document.getElementById(id);\nconst local = ['localhost','127.0.0.1'].includes(location.hostname);\nconst tokenKey = 'blog-bookmarks-admin-token';\nconst choices = [6,10,20];\nconst initialSize = Number(new URLSearchParams(location.search).get('size'));\nconst state = {\n size:choices.includes(initialSize)?initialSize:6,\n recent:[], pending:[], tags:[], remaining:0,\n loading:false, inflight:0, generation:0, changeVersion:0,\n writes:new Map(), busy:new Set()\n};\nconst esc = s => String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst dateText = value => value ? new Intl.DateTimeFormat('zh-TW',{\n timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit',\n hour:'2-digit',minute:'2-digit',hourCycle:'h23'\n}).format(new Date(value)) : '';\nconst levels = ['未讀','已讀','不公開','公開','推薦'];\nconst half = () => state.size/2;\nconst mobileView = () => window.matchMedia('(max-width:650px)').matches;\nlet showPrevious = false;\nfunction message(text='',error=false){\n $('message').textContent=text;\n $('message').classList.toggle('error',error);\n}\nfunction headers(){\n const token=local&&sessionStorage.getItem(tokenKey);\n return token?{Authorization:'Bearer '+token}:{};\n}\nasync function request(path,method='GET',body){\n const response=await fetch('/bookmarks/api/admin'+path,{\n  method,credentials:'same-origin',cache:'no-store',\n  headers:{...headers(),...(body===undefined?{}:{'Content-Type':'application/json'})},\n  body:body===undefined?undefined:JSON.stringify(body)\n });\n const data=await response.json().catch(()=>({error:'伺服器回應格式錯誤'}));\n if(!response.ok)throw Error(data.error||'HTTP '+response.status);\n return data;\n}\nfunction queueWrite(id,action){\n const earlier=state.writes.get(id)||Promise.resolve();\n const task=earlier.catch(()=>{}).then(action);\n state.writes.set(id,task);\n task.then(()=>{if(state.writes.get(id)===task)state.writes.delete(id)},\n   ()=>{if(state.writes.get(id)===task)state.writes.delete(id)});\n return task;\n}\nfunction card(b,kind){\n const target=b.preferred_url||b.redirect_url||b.url;\n const domain=new URL(b.url).hostname;\n const original=b.title_original&&b.title_original!==(b.title_zh||b.title)\n  ?'<div class=\"quick-original\" lang=\"en\">'+esc(b.title_original)+'</div>':'';\n const tags=new Set(b.tags.map(t=>t.toLowerCase()));\n const categoryButtons=state.tags.map(t=>{\n  const selected=tags.has(t.name.toLowerCase());\n  return '<button type=\"button\" class=\"category\" data-tag-name=\"'+esc(t.name)+'\" aria-pressed=\"'+selected+'\">'+esc(t.name_zh||t.name)+'</button>';\n }).join('');\n const actions=[2,3,4].map(level=>{\n  const disabled=(level>=3&&!b.tags.length)||state.busy.has(b.id);\n  const selected=b.status===level;\n  return '<button type=\"button\" data-decision=\"'+level+'\" aria-pressed=\"'+selected+'\"'+(disabled?' disabled':'')+'>'+levels[level]+'</button>';\n }).join('');\n return '<article class=\"quick-item '+kind+'\" data-id=\"'+esc(b.id)+'\" data-kind=\"'+kind+'\" tabindex=\"-1\">'+\n  '<div class=\"quick-main\"><a class=\"quick-title\" href=\"'+esc(target)+'\" target=\"_blank\" rel=\"noopener noreferrer\" data-read>'+esc(b.title_zh||b.title)+' ↗</a>'+\n  original+'<div class=\"quick-date\">'+esc(dateText(b.created_at))+' · '+esc(domain)+'</div>'+\n  (b.summary?'<p class=\"quick-summary\">'+esc(b.summary)+'</p>':'')+\n  '<div class=\"quick-actions\">'+actions+\n  '<button type=\"button\" data-edit>編輯</button></div></div>'+\n  '<aside class=\"quick-categories\" aria-label=\"分類\">'+categoryButtons+'</aside>'+\n  '<button type=\"button\" class=\"quick-delete\" data-delete>刪除</button></article>';\n}\n\nfunction findCard(id){\n return [...$('items').querySelectorAll('.quick-item')].find(x=>x.dataset.id===id);\n}\nfunction firstPending(){\n return $('items').querySelector('.quick-item[data-kind=\"pending\"]');\n}\nfunction focusNext(){\n const next=firstPending();\n if(!next)return;\n next.focus({preventScroll:true});\n ($('items').querySelector('.pending-label')||next).scrollIntoView({block:'start',behavior:'instant'});\n}\nfunction render({focus=false,preserveId=null}={}){\n const anchor=preserveId?findCard(preserveId):null;\n const top=anchor?.getBoundingClientRect().top;\n const mobile=mobileView();\n const recent=state.recent.slice(-(mobile?1:half()));\n const pending=state.pending.slice(0,mobile?1:half());\n const last=state.recent.at(-1);\n const lastTags=last?.tags.map(name=>{\n  const t=state.tags.find(t=>t.name.toLowerCase()===name.toLowerCase());\n  return esc(t?.name_zh||t?.name||name);\n }).join('、');\n const lastLabel=last?'<button type=\"button\" class=\"quick-latest\" data-toggle-previous aria-expanded=\"'+String(mobile&&showPrevious)+'\" title=\"查看或收起上一筆已處理書籤\">'+\n  esc(last.status===4?'已推薦':last.status===3?'已公開':'不公開')+\n  (lastTags?' · '+lastTags:'')+'</button>':'';\n const showHistory=!mobile||showPrevious;\n $('items').innerHTML=\n  (showHistory&&recent.length?'<div class=\"quick-section-label\">最近已處理 · '+recent.length+' 筆</div>':'')+\n  (showHistory?recent.map(b=>card(b,'recent')).join(''):'')+\n  '<div class=\"quick-section-label pending-label\"><span>待處理 '+state.remaining.toLocaleString('zh-TW')+' 筆</span>'+lastLabel+'</div>'+\n  (pending.length?pending.map(b=>card(b,'pending')).join(''):\n   '<p class=\"empty\">'+(state.remaining?'正在載入待處理書籤…':'目前已全部處理完成。')+'</p>');\n if(focus){focusNext();return;}\n if(top!==undefined){\n  const next=findCard(preserveId);\n  if(next)window.scrollBy({top:next.getBoundingClientRect().top-top,behavior:'instant'});\n }\n}\n\nfunction updateCard(b){\n const item=findCard(b.id);\n if(!item)return;\n const wasFocused=item===document.activeElement;\n const kind=item.dataset.kind;\n const categoriesScroll=item.querySelector('.quick-categories')?.scrollTop||0;\n item.outerHTML=card(b,kind);\n const replacement=findCard(b.id);\n const categories=replacement?.querySelector('.quick-categories');\n if(categories)categories.scrollTop=categoriesScroll;\n if(wasFocused)replacement?.focus({preventScroll:true});\n}\nasync function load(size=state.size,{focus=true}={}){\n const generation=++state.generation;\n state.loading=true;\n message('載入中…');\n try{\n  const [data,tags]=await Promise.all([request('/quick?size='+size),request('/tags')]);\n  if(generation!==state.generation)return;\n  state.size=size;\n  state.recent=data.recent;\n  state.pending=data.pending;\n  state.remaining=data.remaining;\n  state.tags=tags;\n  state.loading=false;\n  $('size').value=String(size);\n  render({focus});\n  message('');\n }catch(error){\n  if(generation===state.generation){state.loading=false;message(error.message,true);}\n }\n}\n// Reconcile only once all decisions have finished. Ignore responses overtaken by\n// new user actions; this prevents a stale fetch from bringing back processed cards.\nasync function reconcile(){\n if(state.inflight||state.loading)return;\n const version=state.changeVersion;\n const generation=state.generation;\n const anchor=firstPending()?.dataset.id;\n try{\n  const [data,tags]=await Promise.all([\n   request('/quick?size='+state.size),request('/tags')\n  ]);\n  if(generation!==state.generation||version!==state.changeVersion||state.inflight)return;\n  state.recent=data.recent;\n  state.pending=data.pending;\n  state.remaining=data.remaining;\n  state.tags=tags;\n  render({preserveId:anchor});\n }catch(error){message('已儲存，但同步清單失敗：'+error.message,true);}\n}\nfunction takeDecision(b,level){\n if(state.busy.has(b.id)||state.loading)return;\n if(level>=3&&!b.tags.length){message('請先選擇至少一個分類，才能公開或推薦',true);return;}\n const oldStatus=b.status;\n if(oldStatus===level)return;\n const previousRecent=[...state.recent];\n const wasPending=oldStatus<2;\n state.busy.add(b.id);\n state.inflight++;\n state.changeVersion++;\n const next={...b,status:level};\n showPrevious=false;\n state.pending=state.pending.filter(x=>x.id!==b.id);\n state.recent=[...state.recent.filter(x=>x.id!==b.id),next].slice(-half());\n if(wasPending)state.remaining--;\n render({focus:wasPending,preserveId:wasPending?null:b.id});\n message('已選擇「'+levels[level]+'」，正在儲存…');\n queueWrite(b.id,()=>request('/'+b.id,'PATCH',{status:level,tags:[...b.tags]}))\n .then(()=>{\n  message('已儲存：'+levels[level]);\n },error=>{\n  // Restore the preceding state on failure; never silently discard a decision.\n  // Roll back only this record: other pending decisions may have advanced already.\n  state.recent=state.recent.filter(x=>x.id!==b.id);\n  if(wasPending){\n   if(!state.pending.some(x=>x.id===b.id)){\n    state.pending=[...state.pending,{...b,status:oldStatus}]\n     .sort((a,z)=>z.created_at.localeCompare(a.created_at)||z.id.localeCompare(a.id));\n    state.remaining++;\n   }\n  }else{\n   const original=previousRecent.find(x=>x.id===b.id)||{...b,status:oldStatus};\n   const position=previousRecent.findIndex(x=>x.id===b.id);\n   state.recent.splice(Math.min(Math.max(0,position),state.recent.length),0,original);\n   state.recent=state.recent.slice(-half());\n  }\n  state.changeVersion++;\n  render({focus:wasPending,preserveId:wasPending?null:b.id});\n  message('儲存失敗：'+error.message,true);\n }).finally(()=>{\n  state.busy.delete(b.id);\n  state.inflight--;\n  if(!state.inflight)void reconcile();\n });\n}\nfunction changeTag(b,name){\n if(state.busy.has(b.id)||state.loading)return;\n const old=[...b.tags];\n const selected=old.some(t=>t.toLowerCase()===name.toLowerCase());\n if(selected&&b.status>=3&&old.length===1){\n  message('公開或推薦的書籤必須保留至少一個分類；可先改成不公開',true);\n  return;\n }\n const next=selected?old.filter(t=>t.toLowerCase()!==name.toLowerCase()):[...old,name];\n b.tags=next;\n state.changeVersion++;\n updateCard(b);\n const version=state.changeVersion;\n queueWrite(b.id,()=>request('/'+b.id,'PATCH',{tags:next}))\n .then(()=>{\n  if(version===state.changeVersion)message('分類已儲存');\n },error=>{\n  if(b.tags===next || b.tags.join('\\0')===next.join('\\0')){\n   b.tags=old;updateCard(b);\n  }\n  message('分類儲存失敗：'+error.message,true);\n });\n}\nfunction edit(b){\n if(state.busy.has(b.id))return;\n $('editId').value=b.id;\n $('editTitle').value=b.title_zh||b.title||'';\n $('editOriginalTitle').value=b.title_original||'';\n $('editUrl').value=b.url||'';\n $('editRedirectUrl').value=b.redirect_url||'';\n $('editSummary').value=b.summary||'';\n $('editDialog').showModal();\n}\nfunction deleteBookmark(b){\n if(state.busy.has(b.id)||state.loading)return;\n if(!confirm('確定永久刪除這筆書籤？'))return;\n const wasPending=b.status<2;\n state.busy.add(b.id);\n state.inflight++;\n state.changeVersion++;\n showPrevious=false;\n state.recent=state.recent.filter(item=>item.id!==b.id);\n state.pending=state.pending.filter(item=>item.id!==b.id);\n if(wasPending)state.remaining--;\n render({focus:wasPending});\n message('正在刪除…');\n queueWrite(b.id,()=>request('/'+b.id,'DELETE')).then(result=>{\n  if(!result.deleted)throw Error('找不到書籤');\n  message('已刪除');\n },error=>{\n  if(wasPending){\n   state.pending.push(b);\n   state.pending.sort((a,z)=>z.created_at.localeCompare(a.created_at)||z.id.localeCompare(a.id));\n   state.remaining++;\n  }else state.recent=[...state.recent,b].slice(-half());\n  state.changeVersion++;\n  render({focus:wasPending});\n  message('刪除失敗：'+error.message,true);\n }).finally(()=>{\n  state.busy.delete(b.id);\n  state.inflight--;\n  if(!state.inflight)void reconcile();\n });\n}\n$('app').innerHTML=\n '<header class=\"quick-header\"><h1>書籤快速處理</h1><nav><a href=\"/bookmarks/admin/\">完整管理</a> · <a href=\"/bookmarks/\" target=\"_blank\" rel=\"noopener\">公開列表 ↗</a></nav></header>'+\n '<div class=\"quick-toolbar\"><select id=\"size\" aria-label=\"顯示數量\">'+\n '<option value=\"6\">3＋3</option><option value=\"10\">5＋5</option>'+\n '<option value=\"20\">10＋10</option></select></div>'+\n '<div class=\"auth\" id=\"auth\"></div>'+\n '<div id=\"message\" role=\"status\" aria-live=\"polite\"></div>'+\n '<main id=\"items\" aria-label=\"快速處理清單\"></main>'+\n '<dialog id=\"editDialog\" aria-labelledby=\"editHeading\"><form id=\"editForm\">'+\n '<h2 id=\"editHeading\">編輯書籤</h2><input id=\"editId\" type=\"hidden\">'+\n '<label>繁體中文標題<input id=\"editTitle\" required maxlength=\"500\" autocomplete=\"off\"></label>'+\n '<label>原文標題<input id=\"editOriginalTitle\" maxlength=\"500\" autocomplete=\"off\"></label>'+\n '<label>原始網址<input id=\"editUrl\" type=\"url\" required></label>'+\n '<label>重導向網址<input id=\"editRedirectUrl\" type=\"url\"></label>'+\n '<label>摘要<textarea id=\"editSummary\" maxlength=\"5000\"></textarea></label>'+\n '<div class=\"dialog-actions\"><button id=\"saveEdit\" type=\"submit\">儲存</button><button id=\"cancelEdit\" type=\"button\">取消</button></div>'+\n '</form></dialog>';\n$('size').value=String(state.size);\n$('cancelEdit').onclick=()=>$('editDialog').close();\n$('editForm').addEventListener('submit',async event=>{\n event.preventDefault();\n const id=$('editId').value;\n const b=[...state.recent,...state.pending].find(x=>x.id===id);\n if(!b||state.busy.has(id))return;\n const raw={\n  title_zh:$('editTitle').value.trim(),\n  title_original:$('editOriginalTitle').value.trim(),\n  url:$('editUrl').value.trim(),\n  redirect_url:$('editRedirectUrl').value.trim(),\n  summary:$('editSummary').value.trim()\n };\n if(!raw.title_zh||!raw.url)return;\n state.busy.add(id);\n state.inflight++;\n state.changeVersion++;\n $('saveEdit').disabled=true;\n $('cancelEdit').disabled=true;\n try{\n  const updated=await queueWrite(id,()=>request('/'+id,'PATCH',raw));\n  Object.assign(b,updated);\n  updateCard(b);\n  $('editDialog').close();\n  message('已儲存');\n }catch(error){message('編輯失敗：'+error.message,true);}\n finally{\n  state.busy.delete(id);\n  state.inflight--;\n  $('saveEdit').disabled=false;\n  $('cancelEdit').disabled=false;\n  if(!state.inflight)void reconcile();\n }\n});\n$('size').addEventListener('change',()=>{\n const size=Number($('size').value);\n if(!choices.includes(size))return;\n const url=new URL(location.href);\n if(size===6)url.searchParams.delete('size');else url.searchParams.set('size',String(size));\n history.replaceState(history.state,'',url.href);\n void load(size);\n});\nif(local){\n $('auth').innerHTML='<input id=\"token\" type=\"password\" autocomplete=\"off\" placeholder=\"本機管理 Token\"><button type=\"button\" id=\"login\">登入</button>';\n $('token').value=sessionStorage.getItem(tokenKey)||'';\n $('login').addEventListener('click',()=>{\n  sessionStorage.setItem(tokenKey,$('token').value);\n  void load();\n });\n}\n$('items').addEventListener('click',event=>{\n if(event.target.closest('[data-toggle-previous]')){\n  if(!mobileView())return;\n  showPrevious=!showPrevious;\n  render();\n  const destination=$('items').querySelector(showPrevious?'.quick-item.recent':'.pending-label');\n  destination?.scrollIntoView({block:'start',behavior:'instant'});\n  return;\n }\n const element=event.target.closest('.quick-item');\n if(!element)return;\n const b=[...state.recent,...state.pending].find(x=>x.id===element.dataset.id);\n if(!b)return;\n if(event.target.closest('[data-edit]')){edit(b);return;}\n if(event.target.closest('[data-delete]')){deleteBookmark(b);return;}\n const tag=event.target.closest('[data-tag-name]');\n if(tag){changeTag(b,tag.dataset.tagName);return;}\n const decision=event.target.closest('[data-decision]');\n if(decision){takeDecision(b,Number(decision.dataset.decision));return;}\n if(event.target.closest('[data-read]')&&b.status===0){\n  // Opening the source does not advance the queue; it only marks it read.\n  b.status=1;\n  queueWrite(b.id,()=>request('/'+b.id,'PATCH',{status:1}))\n   .catch(error=>message('已開啟原文，但標記已讀失敗：'+error.message,true));\n }\n});\nwindow.matchMedia('(max-width:650px)').addEventListener('change',()=>{showPrevious=false;render();});\nvoid load();\n";
export const quickStylesheet = "/* Compact quick review UI; shared theme and edit dialog come from admin.css. */\n#app{max-width:1160px;padding-top:12px}\n.quick-header{margin-bottom:5px}\n.quick-header h1{font-size:1.3rem}\n.quick-header nav{font-size:.83rem;text-align:right}\n.quick-toolbar{display:flex;justify-content:flex-end;padding:2px 0 7px}\n.quick-toolbar select{width:auto;min-width:86px;font-size:.81rem;padding:5px 8px}\n.auth:empty,#message:empty{display:none}\n#message{margin:4px 0 8px;min-height:0}\n.quick-section-label{font-size:.83rem;color:var(--muted);font-weight:700;padding:9px 3px 4px}\n.pending-label{display:grid;grid-template-columns:max-content minmax(0,1fr);align-items:start;gap:8px;scroll-margin-top:10px}\n.pending-label>span:first-child{white-space:nowrap;color:var(--ink)}\n.quick-latest{justify-self:end;max-width:100%;text-align:right;font-size:.8rem;color:var(--accent);font-weight:560;line-height:1.5;overflow-wrap:anywhere;border:0;background:transparent;padding:0;cursor:pointer}\n.quick-item{display:grid;grid-template-columns:minmax(0,1fr) clamp(112px,17vw,178px);gap:11px;scroll-margin-top:12px;background:var(--surface);border:1px solid var(--line);border-radius:10px;margin:7px 0;padding:12px 14px 62px;position:relative;overflow-wrap:anywhere}\n.quick-item:focus{outline:2px solid var(--accent);outline-offset:1px}\n.quick-item.recent{opacity:.8}\n.quick-item.pending{border-left:3px solid var(--accent)}\n.quick-main{min-width:0}\n.quick-title{font-size:1.05rem;line-height:1.47;font-weight:680}\n.quick-original{font-size:.82rem;line-height:1.43;color:var(--muted);margin-top:3px}\n.quick-date{font-size:.76rem;color:var(--muted);font-variant-numeric:tabular-nums;margin-top:4px}\n.quick-summary{font-size:.9rem;line-height:1.73;white-space:pre-wrap;color:var(--muted);margin:11px 0 12px;overflow-wrap:anywhere}\n.quick-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}\n.quick-actions button{font-size:.81rem;padding:5px 9px}\n.quick-actions button[data-decision=\"3\"]{background:var(--soft);color:var(--accent)}\n.quick-actions button[data-decision=\"4\"]{background:var(--accent);color:white;border-color:var(--accent)}\n.quick-actions button[aria-pressed=\"true\"]{outline:2px solid var(--accent);outline-offset:1px}\n.quick-item>.quick-delete{position:absolute;right:14px;bottom:12px;font-size:.81rem;padding:5px 9px;color:#dc2626;border-color:#dc2626;background:transparent}\n.quick-item>.quick-delete:hover:enabled{color:#fff;background:#dc2626;border-color:#dc2626}\n.quick-categories{border-left:1px solid var(--line);padding-left:10px;display:flex;flex-direction:column;align-items:stretch;gap:4px}\n.quick-categories .category{font-size:.79rem;line-height:1.3;padding:5px 5px;text-align:left;white-space:normal;word-break:break-word;flex-shrink:0}\n.quick-categories .category[aria-pressed=\"true\"]{border-color:var(--accent);background:var(--soft);color:var(--accent);font-weight:700}\n.empty{padding:18px 10px;color:var(--muted)}\n@media(max-width:650px){\n #app{padding:9px 8px 55px}\n .quick-header h1{font-size:1.12rem}\n .quick-toolbar{display:none}\n .quick-toolbar select{font-size:.78rem}\n .quick-section-label{padding:7px 2px 3px}\n .quick-latest{font-size:.75rem}\n .quick-item{grid-template-columns:minmax(0,1fr) 93px;gap:7px;padding:10px 8px 60px;margin:7px 0}\n .quick-title{font-size:.99rem}\n .quick-original{font-size:.75rem}\n .quick-date{font-size:.72rem}\n .quick-summary{font-size:.87rem;line-height:1.68}\n .quick-actions{gap:5px}\n .quick-actions button{font-size:.76rem;padding:5px 6px}\n .quick-item>.quick-delete{right:8px;bottom:10px;font-size:.76rem;padding:5px 9px}\n .quick-categories{padding-left:6px;gap:4px}\n .quick-categories .category{font-size:.76rem;padding:6px 4px}\n}\n";
